public void Main(Scanner sc) {
    // Read input
    int n = sc.nextInt();
    int m = sc.nextInt();
    sc.nextLine();

    List<Integer> A = new ArrayList<>();
    List<Integer> B = new ArrayList<>();

    for (int i = 0; i < n; i++) {
        A.add(sc.nextInt());
    }
    sc.nextLine();
    for (int i = 0; i < m; i++) {
        B.add(sc.nextInt());
    }

    // Combine lists A and B into C
    List<Integer> C = new ArrayList<>(A);
    C.addAll(B);

    // Sort list C
    Collections.sort(C);

    // Check for consecutive elements in C that both belong to A
    for (int i = 0; i < C.size() - 1; i++) {
        if (A.contains(C.get(i)) && A.contains(C.get(i + 1))) {
            System.out.println("Yes");
            return;
        }
    }

    System.out.println("No");
}
